613:		occurrences,e:=v.occurrences(owner,"",owner.body);if e!=nil{return nil,nil,e}
614:		if len(rows)!=len(occurrences){return nil,nil,f08Binding}
615:		used:=make([]bool,len(rows));targets:=map[string]any{};sameID:=map[string]string{}
616:		for _,occurrence:=range occurrences{
617:			matched:=-1
618:			for i,row:=range rows {
619:				if used[i] || row[4]!=occurrence.field || row[6]!=occurrence.targetKind || row[7]!=occurrence.targetID {continue}
620:				tp,ok:=row[5].(string);if !ok{return nil,nil,f08Shape}
621:				if tp!=owner.project && !(occurrence.globalFallback && tp=="" && (occurrence.targetKind=="BudgetPolicy" || occurrence.targetKind=="RunPolicy")){continue}
622:				if occurrence.exact!=nil && !f08Equal(row[8],occurrence.exact["revision"]){continue}
623:				matched=i;break
624:			}
625:			if matched<0{return nil,nil,f08Binding}
626:			used[matched]=true;row:=rows[matched]
627:			targetRow,e:=s.one("domain_versions",[]int{0,1,2,3},[]any{row[5],row[6],row[7],row[8]});if e!=nil{return nil,nil,e}
628:			if occurrence.exact!=nil && !f08Equal(targetRow[5],occurrence.exact["content_hash"]){return nil,nil,f08Binding}
629:			target,e:=v.version(s,row[5].(string),map[string]any{"entity_type":row[6],"id":row[7],"revision":row[8],"content_hash":targetRow[5]});if e!=nil{return nil,nil,e}
630:			destination,e:=f08Key([]any{target.project,target.ref()});if e!=nil{return nil,nil,e}
631:			// All repeated ID-only occurrences from one producer resolve the same tuple.
632:			if occurrence.exact==nil {
633:				shape,_:=f08Key([]any{occurrence.field,occurrence.targetKind,occurrence.targetID})
634:				if old,ok:=sameID[shape];ok && old!=destination{return nil,nil,f08Binding};sameID[shape]=destination
635:			}
636:			targets[destination]=target.anchor();anchors[destination]=target.anchor();pending=append(pending,target)
637:		}
638:		rowValues:=make([]any,len(rows));for i,row:=range rows{rowValues[i]=row}
639:		f08SortTuples(rowValues)
