641:	}
642:	result:=make([]any,0,len(closures));for _,item:=range closures{result=append(result,item)}
643:	sort.Slice(result,func(i,j int)bool{
644:		x:=result[i].(map[string]any);y:=result[j].(map[string]any);xr:=x["owner_ref"].(map[string]any);yr:=y["owner_ref"].(map[string]any)
645:		return f08TupleLess([]any{x["owner_project"],xr["entity_type"],xr["id"],xr["revision"],xr["content_hash"]},[]any{y["owner_project"],yr["entity_type"],yr["id"],yr["revision"],yr["content_hash"]})
646:	})
