650:// SQL tuple lexicographic ordering compares scalar columns, not encoded JSON
651:// strings (which would put numeric revision10 before2). String order is UTF8.
652:func f08ScalarCompare(a,b any) int {
653:	if a==nil{if b==nil{return 0};return -1};if b==nil{return 1}
654:	if x,ok:=a.(json.Number);ok {
655:		if y,ok:=b.(json.Number);ok{xr,_:=new(big.Rat).SetString(string(x));yr,_:=new(big.Rat).SetString(string(y));return xr.Cmp(yr)}
656:	}
657:	x,xok:=a.(string);y,yok:=b.(string);if xok && yok{return strings.Compare(x,y)}
658:	xk,_:=f08Key(a);yk,_:=f08Key(b);return strings.Compare(xk,yk)
659:}
660:func f08TupleLess(a,b []any)bool{for i:=0;i<len(a)&&i<len(b);i++{c:=f08ScalarCompare(a[i],b[i]);if c!=0{return c<0}};return len(a)<len(b)}
661:func f08SortTuples(rows []any){sort.Slice(rows,func(i,j int)bool{return f08TupleLess(rows[i].([]any),rows[j].([]any))})}
662:func f08SortedAnchors(values map[string]any)[]any{
663:	a:=make([]any,0,len(values));for _,v:=range values{a=append(a,v)}
664:	sort.Slice(a,func(i,j int)bool{
665:		x:=a[i].(map[string]any);y:=a[j].(map[string]any);xr:=x["version_ref"].(map[string]any);yr:=y["version_ref"].(map[string]any)
666:		return f08TupleLess([]any{x["project"],xr["entity_type"],xr["id"],xr["revision"],xr["content_hash"]},[]any{y["project"],yr["entity_type"],yr["id"],yr["revision"],yr["content_hash"]})
667:	});return a
668:}
