756:		parent,e:=f08FindGroup(s,category,row[:4]);if e!=nil{return e}
757:		want:=map[string]any{"project":row[5],"kind":row[6],"id":row[7],"revision":row[8],"content_hash":row[9]}
758:		matches:=0;for _,pin:=range parent.pins{if f08Equal(pin,want){matches++}}
759:		if matches!=1{return f08Binding}
760:		_,e=v.version(s,row[5].(string),map[string]any{"entity_type":row[6],"id":row[7],"revision":row[8],"content_hash":row[9]});return e
761:	}
762:	category,child:="admitted","admitted_members";if action=="final_member.insert"{category,child="final","final_members"}else if action!="admitted_member.insert"{return f08Mode}
763:	if e:=f08ValidateTuple(child,row);e!=nil{return e};parent,e:=f08FindGroup(s,category,row[:4]);if e!=nil{return e}
764:	index,e:=f08Integer(row[5],0);if e!=nil || index>=int64(len(parent.members)){return f08Binding}
765:	want:=parent.members[index].(map[string]any);actual,_,e:=f08RawObject(row[8]);if e!=nil || !f08Equal(actual,want){return f08Binding}
766:	h,e:=f08Hash(actual);if e!=nil || h!=row[7]{return f08Binding}
767:	key:="task_ref";if category=="final"{key="task_admitted_ref"}
768:	if actual[key].(map[string]any)["id"]!=row[4]{return f08Binding}
