770:		admitted,e:=f08FindGroup(s,"admitted",row[:4]);if e!=nil || index>=int64(len(admitted.members)){return f08Binding}
771:		original:=admitted.members[index].(map[string]any);h,e:=f08Hash(original);if e!=nil || h!=row[6]{return f08Binding}
772:		if !f08Equal(actual["admitted_member_ref"],f08MemberReference("ADMITTED",row[4].(string),h)){return f08Binding}
773:	}
774:	return nil
775:}
