694:func f08ParseGroup(category string,row []any)(*f08Group,error){
695:	if category!="admitted" && category!="final"{return nil,f08Mode}
696:	if e:=f08ValidateTuple(category,row);e!=nil{return nil,e}
697:	docIndex,rootIndex,groupIndex:=8,6,7;phase:="ADMITTED"
698:	if category=="final"{docIndex,rootIndex,groupIndex=7,5,6;phase="FINALIZED"}
699:	document,_,e:=f08RawObject(row[docIndex]);if e!=nil{return nil,e}
700:	if _,e=f08Object(document,"root","members","pins");e!=nil{return nil,e}
701:	root,ok:=document["root"].(map[string]any);if !ok{return nil,f08Shape}
702:	if category=="admitted" {
703:		_,e=f08Object(root,"format","phase","principal","project","command_id","method","operation","key","request_hash","client_id","session_binding","target_binding","private_header_digest","member_task_ids","member_count")
704:	} else {
705:		_,e=f08Object(root,"format","phase","admitted_root_ref","principal","project","command_id","request_hash","control_request_id","completion_mode","original_response_digest","final_response_digest","final_snapshot_binding","member_count")
706:	}
707:	if e!=nil{return nil,e}
708:	if root["format"]!=f08Format || root["phase"]!=phase{return nil,f08Binding}
709:	for i,key:=range []string{"principal","project","command_id","request_hash"}{if root[key]!=row[i]{return nil,f08Binding}}
710:	rootHash,e:=f08Hash(root);if e!=nil || rootHash!=row[rootIndex]{return nil,f08Binding}
711:	members,e:=f08Array(document["members"]);if e!=nil || len(members)==0{return nil,f08Shape}
712:	count,e:=f08Integer(root["member_count"],1);if e!=nil || count!=int64(len(members)){return nil,f08Binding}
713:	pins,e:=f08Array(document["pins"]);if e!=nil{return nil,e}
714:	var digests []any;last:=""
715:	for _,item:=range members{
716:		member,ok:=item.(map[string]any);if !ok{return nil,f08Shape}
717:		refKey:="task_ref"
718:		if phase=="ADMITTED"{
719:			_,e=f08Object(member,"format","phase","admitted_root_ref","task_ref","goal_ref","run_ref","runtime_binding","dispatch_stage","dispatch_origin_ref","queue_admission","reference_closure")
720:			if !f08Equal(member["admitted_root_ref"],f08RootReference(phase,rootHash)){return nil,f08Binding}
721:		} else {
722:			refKey="task_admitted_ref"
723:			_,e=f08Object(member,"format","phase","admitted_member_ref","proof_kind","task_admitted_ref","run_admitted_ref","run_before_settlement_ref","run_final_ref","task_final_ref","dispatch_origin_ref","dispatch_final_binding","queue_final_binding","effect_closure","observation_ref","native_artifact_refs","sdk_receipt_refs","run_event_ref","task_event_ref","reference_closure","prior_epoch_closure","prelaunch_checkpoint_carry")
724:		}
725:		if e!=nil || member["format"]!=f08Format || member["phase"]!=phase{return nil,f08Shape}
726:		ref,e:=f08Object(member[refKey],"entity_type","id","revision","content_hash");if e!=nil || ref["entity_type"]!="Task"{return nil,f08Shape}
727:		id,e:=f08String(ref["id"]);if e!=nil || id<=last{return nil,f08Binding};last=id
728:		h,e:=f08Hash(member);if e!=nil{return nil,e};digests=append(digests,map[string]any{"task_id":id,"member_hash":h})
729:	}
730:	groupHash,e:=f08Hash(digests);if e!=nil || groupHash!=row[groupIndex]{return nil,f08Binding}
731:	if phase=="ADMITTED"{
732:		ids,e:=f08Array(root["member_task_ids"]);if e!=nil || len(ids)!=len(members){return nil,f08Binding}
733:		for i,d:=range digests{if ids[i]!=d.(map[string]any)["task_id"]{return nil,f08Binding}}
734:		if root["method"]!="session.control" || root["operation"]!="v2:session.control" || root["key"]!=row[2] || row[4]!=root["operation"]{return nil,f08Binding}
735:	} else if !f08Equal(root["admitted_root_ref"],f08RootReference("ADMITTED",row[4].(string))) {return nil,f08Binding}
736:	var lastPin []any
737:	for _,item:=range pins{
738:		pin,e:=f08Object(item,"project","kind","id","revision","content_hash");if e!=nil{return nil,e}
739:		p,ok:=pin["project"].(string);if !ok{return nil,f08Shape}
740:		kind,e:=f08String(pin["kind"]);if e!=nil{return nil,e};id,e:=f08String(pin["id"]);if e!=nil{return nil,e}
741:		if _,e=f08Integer(pin["revision"],1);e!=nil{return nil,e}
742:		if pin["content_hash"]!=nil{if _,e=f08HashString(pin["content_hash"]);e!=nil{return nil,e}}
743:		key:=[]any{p,kind,id,pin["revision"],pin["content_hash"]}
744:		if lastPin!=nil && !f08TupleLess(lastPin,key){return nil,f08Binding};lastPin=key
745:	}
746:	return &f08Group{phase,row,root,members,pins,rootHash,groupHash},nil
799:func (v *f08ProofValidator) groupRequest(s *f08Sources,g *f08Group)(f08CancelRequest,error){
800:	var zero f08CancelRequest
801:	if g.phase!="ADMITTED"{return zero,f08Mode}
802:	r:=g.root;binding,e:=f08Object(r["session_binding"],"session_id","accepted_revision","writer_client_id","writer_epoch","lease_expires_at","event_watermark");if e!=nil{return zero,e}
803:	target,e:=f08Object(r["target_binding"],"kind","id","version_ref");if e!=nil{return zero,e}
804:	id,e:=s.one("identities",[]int{0,1},[]any{g.row[0],g.row[2]});if e!=nil{return zero,e}
805:	if id[2]!=ProtocolV2 || id[3]!=g.row[1] || id[4]!="session.control" || id[5]!=g.row[4] || id[6]!=g.row[3]{return zero,f08Binding}
806:	header,e:=f08Hex(g.row[5]);if e!=nil{return zero,e}
807:	identity:=map[string]any{"format":f08IdentityFormat,"principal":id[0],"project":id[3],"operation":id[5],"key":id[1],"request_hash":id[6],"command_id":id[1],"method":id[4],"client_id":r["client_id"],"session_id":binding["session_id"],"writer_epoch":binding["writer_epoch"],"expected_revision":binding["accepted_revision"],"target_id":target["id"]}
808:	b,e:=f08Encode(identity);if e!=nil{return zero,e};req,e:=f08Request(v.protocol,header,b);if e!=nil{return zero,e}
809:	if r["private_header_digest"]!=req.headerDigest || binding["writer_client_id"]!=req.client{return zero,f08Binding}
810:	return req,nil
811:}
812:func (v *f08ProofValidator) queueAdmission(s *f08Sources,project,task string)(map[string]any,error){
813:	q:=map[string]any{"variant":"NO_SESSION","session_id":nil,"generation":nil,"revision":nil,"state":nil,"accepted_through":nil,"sealed_through":nil,"run_id":nil,"runtime_epoch":nil,"dispatch_key":nil,"manifest_hash":nil,"process_identity":nil,"restore_fenced":nil}
814:	sessions:=s.selectRows("sessions",[]int{1,6},[]any{project,task})
815:	fences:=s.selectRows("fences",[]int{0,1},[]any{project,task})
816:	if len(sessions)==0{if len(fences)!=0{return nil,f08Binding};return q,nil}
817:	if len(sessions)!=1{return nil,f08Binding};session:=sessions[0];q["session_id"]=session[0]
818:	if len(fences)==0{q["variant"]="REAL_SESSION_NO_ORIGINAL_FENCE";return q,nil}
819:	if len(fences)!=1 || fences[0][2]!=session[0]{return nil,f08Binding}
820:	f:=fences[0];q["variant"]="ORIGINAL_FENCE"
821:	for key,i:=range map[string]int{"generation":3,"revision":13,"state":4,"accepted_through":5,"sealed_through":6,"run_id":7,"runtime_epoch":8,"dispatch_key":9,"manifest_hash":10,"restore_fenced":12}{q[key]=f[i]}
822:	// The registry fixes actual fence tuple positions; process_identity is raw
823:	// nullable JSON, and revision is the last column (index13 in SQL22).
824:	q["revision"]=f[13]
825:	if f[11]!=nil{identity,_,e:=f08JSONHex(f[11]);if e!=nil{return nil,e};q["process_identity"]=identity}
826:	accepted,e:=f08Integer(f[5],0);if e!=nil{return nil,e};sealed,e:=f08Integer(f[6],0);if e!=nil || sealed>accepted{return nil,f08Binding}
827:	for _,entry:=range s.selectRows("queue",[]int{1,4,6},[]any{project,task,f[3]}){
828:		seq,e:=f08Integer(entry[7],1);if e!=nil || seq>accepted || entry[3]!=session[0]{return nil,f08Binding}
829:		_,contentRaw,e:=f08JSONHex(entry[12]);if e!=nil{return nil,e};if f08RawHash(contentRaw)!=entry[13]{return nil,f08Binding}
830:		if entry[16]!=nil{
831:			r,e:=s.one("receipts",[]int{0,1,2,3},[]any{entry[16],project,f[3],entry[2]});if e!=nil{return nil,e}
832:			_,receiptRaw,e:=f08JSONHex(r[5]);if e!=nil || f08RawHash(receiptRaw)!=r[6]{return nil,f08Binding}
833:		}
834:	}
835:	return q,nil
836:}
837:func (v *f08ProofValidator) noRun(s *f08Sources,task f08Version)error{
838:	if task.body["active_run_id"]!=nil{return f08Binding}
839:	for _,row:=range s.rows["domain_versions"]{
840:		if row[0]!=task.project || row[1]!="Run"{continue}
841:		body,_,e:=f08RawObject(row[4]);if e!=nil{return e};if body["task_id"]==task.id{return f08Binding}
842:	}
843:	for _,row:=range s.rows["dispatches"]{
844:		if row[0]!=task.project{continue};body,_,e:=f08RawObject(row[4]);if e!=nil{return e};if body["task_id"]==task.id{return f08Binding}
845:	}
846:	// Effects bind a Run, not a Task. Every same-project effect must resolve a
847:	// real Run version; an orphan effect cannot be ignored as "not this Task".
848:	for _,row:=range s.rows["effects"]{
849:		if row[0]!=task.project{continue};runs:=s.selectRows("domain_versions",[]int{0,1,2},[]any{task.project,"Run",row[1]});if len(runs)==0{return f08Binding}
850:		for _,run:=range runs{body,_,e:=f08RawObject(run[4]);if e!=nil || body["task_id"]==task.id{return f08Binding}}
851:	}
852:	return nil
853:}
854:func (v *f08ProofValidator) admitted(s *f08Sources,row []any,current bool)(*f08Group,error){
855:	g,e:=f08ParseGroup("admitted",row);if e!=nil{return nil,e};req,e:=v.groupRequest(s,g);if e!=nil{return nil,e}
856:	root:=g.root;binding:=root["session_binding"].(map[string]any);target:=root["target_binding"].(map[string]any)
857:	if target["kind"]!="Goal" && target["kind"]!="Run"{return nil,f08Shape}
858:	targetVersion,e:=v.version(s,req.project,target["version_ref"]);if e!=nil || targetVersion.kind!=target["kind"] || targetVersion.id!=target["id"]{return nil,f08Binding}
859:	if current{
860:		if len(s.selectRows("admitted",[]int{0,1,2},row[:3]))!=0 || len(s.selectRows("idempotency",[]int{0,1,2,3},[]any{row[0],row[1],row[4],row[2]}))!=0{return nil,f08Binding}
861:		session,e:=s.one("sessions",[]int{0,1},[]any{req.session,req.project});if e!=nil{return nil,e}
862:		for key,index:=range map[string]int{"accepted_revision":2,"writer_client_id":9,"writer_epoch":8,"lease_expires_at":10,"event_watermark":11}{if !f08Equal(binding[key],session[index]){return nil,f08Binding}}
863:		if session[21]!=nil || session[22]!=nil || session[23]!=ProtocolV2 || binding["lease_expires_at"]==nil{return nil,f08Binding}
864:		head,e:=v.head(s,req.project,targetVersion.kind,targetVersion.id);if e!=nil || !f08SameVersion(head,targetVersion){return nil,f08Binding}
865:		if targetVersion.kind=="Goal" && session[5]!=targetVersion.id || targetVersion.kind=="Run" && session[7]!=targetVersion.id{return nil,f08Binding}
866:	}
867:	var wantIDs []any
868:	if targetVersion.kind=="Run"{wantIDs=[]any{targetVersion.body["task_id"]}}else if current{
869:		for _,o:=range s.rows["domain_objects"]{
870:			if o[0]!=req.project || o[1]!="Task"{continue};task,e:=v.head(s,req.project,"Task",o[2].(string));if e!=nil{return nil,e}
871:			if task.body["goal_id"]==targetVersion.id{wantIDs=append(wantIDs,task.id)}
