66:		return ok && ok2 && r.Cmp(s) == 0
67:	case map[string]any:
68:		y, ok := b.(map[string]any)
69:		if !ok {
70:			return false
71:		}
72:		for k, v := range x {
73:			if !sameNumbers(v, y[k]) {
74:				return false
75:			}
76:		}
77:	case []any:
